/* 5.1 Initialization / startup */

static void test_avas_init_sets_assigned_fields_to_defaults(void)
{
    AVAS_DATA_BLOCK_s *db = avas_get();

    db->command.turn_left = TRUE;
    db->command.turn_right = TRUE;
    db->command.invalid_vehicle_speed = FALSE;
    db->command.vehicle_speed = 1U;
    db->command.ndr = avas_drive;
    db->manage.dcdc_ready_to_work = TRUE;
    db->manage.obd_avas_command = avas_obd_cmd_drive;
    db->manage.obd_avas_mode = avas_obd_enable;
    db->manage.obd_ndr = avas_drive;
    db->manage.obd_vehicle_speed = 50U;
    db->manage.obd_avas_command_condition = TRUE;
    db->manage.obd_nrc = obd_dcdc_not_ready_nrc;

    avas_init();
    db = avas_get();

    TEST_ASSERT_FALSE(db->command.turn_left);
    TEST_ASSERT_FALSE(db->command.turn_right);
    TEST_ASSERT_TRUE(db->command.invalid_vehicle_speed);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->command.vehicle_speed);
    TEST_ASSERT_EQUAL(avas_invalid, db->command.ndr);
    TEST_ASSERT_FALSE(db->manage.dcdc_ready_to_work);
    TEST_ASSERT_EQUAL(avas_obd_cmd_neutral, db->manage.obd_avas_command);
    TEST_ASSERT_EQUAL(avas_obd_disable, db->manage.obd_avas_mode);
    TEST_ASSERT_EQUAL(avas_neutral, db->manage.obd_ndr);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->manage.obd_vehicle_speed);
    TEST_ASSERT_FALSE(db->manage.obd_avas_command_condition);
    TEST_ASSERT_EQUAL(obd_default_nrc, db->manage.obd_nrc);
}

