static void test_avas_task_init_mode_applies_cfg_speed_zero(void)
{
    avas_init();
    avas_cfg();

    AVAS_DATA_BLOCK_s *db = avas_get();
    DCDC_DATA_BLOCK_s *dcdc_ptr = dcdc_get();
    EV_DATA_BLOCK_s *ev_ptr = ev_get();
    EV_NDR_DATA_BLOCK_s *ev_ndr_ptr = ev_ndr_get();
    HMI_DATA_BLOCK_s *hmi_ptr = hmi_get();
    SYSTEM_MODE_STATE_s *system_mode_ptr = system_mode_get();
    SYSTEM_MODE_STATE_s mode;
    TIME_t local_time;

    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    mode.next = system_mode_initialisation_s;
    ev_ptr->spd.total_kmh = 40.0f;
    dcdc_ptr->manage.dcdc_ready_to_work = TRUE;
    system_mode_ptr->next = system_mode_obd_s;
    hmi_ptr->status.avas_silent = TRUE;
    ev_ndr_ptr->actual_gear = ndr_state_d;

    avas_task(local_time, &mode);

    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->command.vehicle_speed);
    TEST_ASSERT_TRUE(db->command.invalid_vehicle_speed);
    TEST_ASSERT_EQUAL(avas_invalid, db->command.ndr);
    TEST_ASSERT_FALSE(db->manage.dcdc_ready_to_work);
    TEST_ASSERT_EQUAL(avas_obd_disable, db->manage.obd_avas_mode);
    TEST_ASSERT_EQUAL_UINT16(0U, db->manage.obd_vehicle_speed);
    TEST_ASSERT_TRUE(db->manage.hmi_avas_disable);
}

