static void test_avas_update_enables_obd_mode_only_for_obd_enum(void)
{
    avas_init();
    avas_cfg();

    AVAS_DATA_BLOCK_s *db = avas_get();
    DCDC_DATA_BLOCK_s *dcdc_ptr = dcdc_get();
    EV_DATA_BLOCK_s *ev_ptr = ev_get();
    EV_NDR_DATA_BLOCK_s *ev_ndr_ptr = ev_ndr_get();
    HMI_DATA_BLOCK_s *hmi_ptr = hmi_get();
    SYSTEM_MODE_STATE_s *system_mode_ptr = system_mode_get();
    SYSTEM_MODE_STATE_s mode;
    TIME_t local_time;
    uint16_t i;

    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    mode.next = system_mode_warmup_s;
    dcdc_ptr->manage.dcdc_ready_to_work = FALSE;
    hmi_ptr->status.avas_silent = FALSE;
    ev_ptr->spd.total_kmh = 0.0f;
    ev_ndr_ptr->actual_gear = ndr_state_n;

    for (i = 0U; i <= 9U; i++)
    {
        system_mode_ptr->next = (SYSTEM_MODE_STATE_e)i;
        avas_task(local_time, &mode);
        if (system_mode_obd_s == system_mode_ptr->next)
        {
            TEST_ASSERT_EQUAL(avas_obd_enable, db->manage.obd_avas_mode);
        }
        else
        {
            TEST_ASSERT_EQUAL(avas_obd_disable, db->manage.obd_avas_mode);
        }
    }
}

