/* 5.20 Defensive / robustness */

static void test_avas_obd_does_not_write_command_block(void)
{
    avas_init();
    avas_cfg();

    AVAS_DATA_BLOCK_s *db = avas_get();

    db->manage.dcdc_ready_to_work = TRUE;
    db->manage.obd_avas_command = avas_obd_cmd_drive;
    db->command.vehicle_speed = 99U;
    db->command.ndr = avas_parking;
    (void)avas_obd();

    TEST_ASSERT_EQUAL_UINT16(99U, db->command.vehicle_speed);
    TEST_ASSERT_EQUAL(avas_parking, db->command.ndr);
    TEST_ASSERT_EQUAL(avas_drive, db->manage.obd_ndr);
    TEST_ASSERT_EQUAL_UINT16(50U, db->manage.obd_vehicle_speed);
}

